    function getFileSize($path) {
        $rawSize = filesize($path);

        if ($rawSize > 1000) {
            $size = number_format($rawSize / 1000, 2) ." kb";
        } else if ($rawSize <= 1000) {
            return $rawSize ." bytes";
        }

        return $size;
    }
